/**
 * The one-sentence note that the tariff scenario and the four Y are generated by the course (shown at the top of
 * step 10, in the step 11–14 result card and, from gvcsim/regression/teaching.py, in the report).
 */
export const GENERATED_DATA_NOTE = "关税情景与步骤 11–14 的四个 Y 由课程按设定生成（参照真实指标的量级），用于练习读回归，不是真实关税或 OECD 发布的结果。";

export type ReadingDirection = "negative" | "positive" | "insufficient" | "suppressed";

